<?php
include("../config.php");
$pagegen = new page_gen();
$pagegen->round_to = 4;
$pagegen->start();
$s = new Game();
if (!$s->loggedIn || !isset($_GET['time'])) { header("Location: index.php?"); exit; }
$uid = (int)$_SESSION['userid'];
function us_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function us_num($v): string { return number_format((int)$v); }
$metaQ=$s->query("SELECT * FROM universe_meta ORDER BY universe_id LIMIT 1"); $meta=$metaQ?$metaQ->fetch_assoc():null;
if(!$meta){ echo '<div class="universe-seed-module"><h2>Universe seed unavailable</h2><p>Run the universe migration before opening the explorer.</p></div>'; exit; }
$galaxy=max(1,(int)($_GET['galaxy']??1)); $system=max(1,(int)($_GET['system']??1)); $selectedBody=(int)($_GET['body']??0); $status='';
if(isset($_GET['id'])&&$_GET['id']==='discover'){
  $body=(int)($_GET['atype']??0); $type=(string)($_GET['subject']??'scan');
  $allowed=['scan','landing','resource','lifeform','anomaly','artifact'];
  if($body>0&&in_array($type,$allowed,true)){
    $bodyQ=$s->query("SELECT body_id,body_name,body_type FROM universe_bodies WHERE body_id=".$body." LIMIT 1");
    $b=$bodyQ?$bodyQ->fetch_assoc():null;
    if($b){$note='Survey completed on '.date('Y-m-d H:i');$stmt=$s->db_link->prepare("INSERT INTO universe_discoveries (uid,body_id,discovery_type,notes) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE notes=VALUES(notes), discovered_at=NOW()");$stmt->bind_param('iiss',$uid,$body,$type,$note);$stmt->execute();$effectMap=['scan'=>['survey_accuracy',5],'landing'=>['settlement_readiness',8],'resource'=>['resource_output',10],'lifeform'=>['research_output',10],'anomaly'=>['anomaly_insight',12],'artifact'=>['technology_recovery',15]];$effectKey=$effectMap[$type][0]??'survey_accuracy';$effectValue=$effectMap[$type][1]??5;$effectStmt=$s->db_link->prepare("INSERT INTO universe_effects (uid,body_id,effect_key,effect_value,source_discovery_id) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE effect_value=VALUES(effect_value), active=1");$discoveryId=(int)$s->db_link->insert_id;$effectStmt->bind_param('iisii',$uid,$body,$effectKey,$effectValue,$discoveryId);$effectStmt->execute();if($type==='resource'){$s->query("UPDATE player_resources SET metal=metal+500, crystal=crystal+250 WHERE uid=".$uid." LIMIT 1");}$status='<div class="us-alert success">Discovery logged: '.us_h($b['body_name']).' / '.us_h($type).'. Gameplay effect applied: +'.(int)$effectValue.' '.$effectKey.'.</div>'; $selectedBody=$body;}
  }
}
$starsQ=$s->query("SELECT * FROM universe_stars WHERE universe_id=".(int)$meta['universe_id']." AND galaxy_no=".$galaxy." ORDER BY system_no");$stars=[];if($starsQ)while($r=$starsQ->fetch_assoc())$stars[]=$r;
$starQ=$s->query("SELECT * FROM universe_stars WHERE universe_id=".(int)$meta['universe_id']." AND galaxy_no=".$galaxy." AND system_no=".$system." LIMIT 1");$star=$starQ?$starQ->fetch_assoc():null;
$bodies=[];$detail=null;$designs=[];$effects=[];if($star){$bq=$s->query("SELECT * FROM universe_bodies WHERE star_id=".(int)$star['star_id']." ORDER BY body_type,body_no,body_id");if($bq)while($r=$bq->fetch_assoc())$bodies[]=$r;if($selectedBody>0){$dq=$s->query("SELECT * FROM universe_bodies WHERE body_id=".$selectedBody." AND star_id=".(int)$star['star_id']." LIMIT 1");$detail=$dq?$dq->fetch_assoc():null;if($detail){$designQ=$s->query("SELECT * FROM universe_designs WHERE body_id=".(int)$detail['body_id']." ORDER BY design_type");if($designQ)while($r=$designQ->fetch_assoc())$designs[]=$r;$effectQ=$s->query("SELECT * FROM universe_effects WHERE uid=".$uid." AND body_id=".(int)$detail['body_id']." AND active=1 ORDER BY effect_key");if($effectQ)while($r=$effectQ->fetch_assoc())$effects[]=$r;}}}
$disc=[];$dq=$s->query("SELECT body_id,discovery_type FROM universe_discoveries WHERE uid=".$uid);if($dq)while($r=$dq->fetch_assoc())$disc[(int)$r['body_id'].':'.$r['discovery_type']]=true;
?>
<div class="universe-seed-module"><div class="us-header"><div><span class="us-kicker">PROCEDURAL EXPANSE // SEED <?= us_h($meta['seed']); ?></span><h2><?= us_h($meta['universe_name']); ?></h2><p>A deterministic exploration network of galaxies, stars, worlds, moons, stations, anomalies, and precursor signals.</p></div><div class="us-seed-badge">GALAXIES <strong><?= us_num($meta['galaxy_count']); ?></strong><br>DISCOVERY NETWORK <strong>ACTIVE</strong></div></div><?= $status ?><div class="us-toolbar"><label>Galaxy <select onchange="sendData('universe_seed','get','mainDisplay','galaxy='+this.value+'&system=1')"><?php for($g=1;$g<=(int)$meta['galaxy_count'];$g++): ?><option value="<?= $g; ?>" <?= $g===$galaxy?'selected':''; ?>>Galaxy <?= $g; ?></option><?php endfor; ?></select></label><span>System <?= us_num($system); ?> / <?= us_num(count($stars)); ?></span></div><div class="us-layout"><aside class="us-stars"><h3>Star Systems</h3><?php foreach($stars as $st): ?><a class="us-star <?= (int)$st['system_no']===$system?'active':''; ?>" href="javascript:void(0)" onclick="sendData('universe_seed','get','mainDisplay','galaxy=<?= $galaxy; ?>&system=<?= (int)$st['system_no']; ?>');return false"><b>G<?= $galaxy; ?>-S<?= (int)$st['system_no']; ?></b><span><?= us_h($st['star_name']); ?></span><small><?= us_h($st['star_class']); ?> class · <?= us_h($st['hazard']); ?></small></a><?php endforeach; ?></aside><section class="us-main"><?php if($star): ?><div class="us-star-head"><div><span class="us-kicker">SYSTEM G<?= $galaxy; ?>-S<?= (int)$star['system_no']; ?></span><h3><?= us_h($star['star_name']); ?></h3><p><?= us_h($star['star_class']); ?> class / <?= us_h($star['spectral_color']); ?> spectrum / luminosity <?= us_num($star['luminosity']); ?></p></div><span class="us-hazard"><?= us_h($star['hazard']); ?></span></div><div class="us-body-grid"><?php foreach($bodies as $b): $is=$selectedBody===(int)$b['body_id']; ?><a class="us-body <?= $is?'active':''; ?>" href="javascript:void(0)" onclick="sendData('universe_seed','get','mainDisplay','galaxy=<?= $galaxy; ?>&system=<?= $system; ?>&body=<?= (int)$b['body_id']; ?>');return false"><span class="us-body-type"><?= strtoupper(substr($b['body_type'],0,2)); ?></span><span><b><?= us_h($b['body_name']); ?></b><small><?= us_h($b['class_code']); ?>-class <?= us_h($b['subclass_code']); ?> · <?= us_h($b['biome_family']); ?></small><em><?= us_h($b['resource_primary']); ?></em></span><i><?= (int)$b['habitability']; ?>%</i></a><?php endforeach; ?></div><?php if($detail): ?><div class="us-detail"><div class="us-detail-head"><div><span class="us-kicker"><?= strtoupper(us_h($detail['body_type'])); ?> PROFILE</span><h3><?= us_h($detail['body_name']); ?></h3></div><span class="us-seed-code"><?= us_h($detail['seed_code']); ?></span></div><div class="us-facts"><div><span>Class</span><strong><?= us_h($detail['class_code']); ?> — <?= us_h($detail['class_name']); ?></strong></div><div><span>Subclass</span><strong><?= us_h($detail['subclass_code']); ?> — <?= us_h($detail['subclass_name']); ?></strong></div><div><span>Size Rating</span><strong><?= (int)$detail['size_rating']; ?> / 9</strong></div><div><span>Climate</span><strong><?= us_h($detail['climate']); ?></strong></div><div><span>Biome Family</span><strong><?= us_h($detail['biome_family']); ?></strong></div><div><span>Sub-Biome</span><strong><?= us_h($detail['sub_biome']); ?></strong></div><div><span>Biome</span><strong><?= us_h($detail['biome']); ?></strong></div><div><span>Atmosphere</span><strong><?= us_h($detail['atmosphere']); ?></strong></div><div><span>Lifeform</span><strong><?= us_h($detail['lifeform']); ?></strong></div><div><span>Primary Resource</span><strong><?= us_h($detail['resource_primary']); ?></strong></div><div><span>Secondary Resource</span><strong><?= us_h($detail['resource_secondary']); ?></strong></div><div><span>Richness</span><strong><?= (int)$detail['richness']; ?>%</strong></div><div><span>Hazard</span><strong><?= us_h($detail['hazard']); ?></strong></div></div><div class="us-intelligence"><h4>Deep Intelligence</h4><p><b>Geology:</b> <?= us_h($detail['geology_profile']); ?></p><p><b>Ecology:</b> <?= us_h($detail['ecology_profile']); ?></p><p><b>Climate:</b> <?= us_h($detail['climate_profile']); ?></p><p><b>Atmosphere:</b> <?= us_h($detail['atmosphere_profile']); ?></p><p><b>Resources:</b> <?= us_h($detail['resource_profile']); ?></p><p><b>Hazard model:</b> <?= us_h($detail['hazard_profile']); ?></p><p><b>Faction:</b> <?= us_h($detail['faction_presence']); ?> · <b>Settlement:</b> <?= us_h($detail['settlement_class']); ?></p><p><b>Technology level:</b> <?= (int)$detail['technology_level']; ?>/9 · <b>Power affinity:</b> <?= (int)$detail['power_affinity']; ?> · <b>Economy:</b> <?= (int)$detail['economy_value']; ?> · <b>Survey difficulty:</b> <?= (int)$detail['survey_difficulty']; ?></p><p class="us-effect"><b>Base gameplay effect:</b> <?= us_h($detail['gameplay_effect']); ?></p></div><?php if($designs): ?><div class="us-designs"><h4>Design Systems</h4><?php foreach($designs as $design): ?><div class="us-design"><b><?= us_h($design['design_name']); ?></b><span><?= us_h($design['design_type']); ?> · Level <?= (int)$design['design_level']; ?> · <?= (int)$design['unlocked']?'Unlocked':'Blueprint Locked'; ?></span><small><?= us_num($design['metal_cost']); ?> Metal · <?= us_num($design['crystal_cost']); ?> Crystal · <?= us_num($design['deuterium_cost']); ?> Deuterium · <?= us_num($design['power_draw']); ?> Power Draw · +<?= (int)$design['output_bonus']; ?> Output</small></div><?php endforeach; ?></div><?php endif; ?><?php if($effects): ?><div class="us-effects"><h4>Active Discovery Effects</h4><?php foreach($effects as $effect): ?><span><?= us_h($effect['effect_key']); ?> +<?= (int)$effect['effect_value']; ?></span><?php endforeach; ?></div><?php endif; ?><div class="us-actions"><?php foreach(['scan'=>'Scan','landing'=>'Land / Survey','resource'=>'Map Resources','lifeform'=>'Study Lifeform','anomaly'=>'Analyze Anomaly','artifact'=>'Recover Artifact'] as $k=>$label): if($k==='anomaly'&&$detail['body_type']!=='anomaly')continue; ?><a href="javascript:void(0)" onclick="sendData('universe_seed','get','discover','<?= (int)$detail['body_id']; ?>','<?= $k; ?>');return false"><?= $label; ?><?= isset($disc[$detail['body_id'].':'.$k])?' ✓':''; ?></a><?php endforeach; ?></div></div><?php endif; ?><?php else: ?><div class="us-empty">No star system found in this sector.</div><?php endif; ?></section></div></div>
